 @PostMapping("/announcements") public ResponseEntity<?> announcement(HttpServletRequest r,@RequestBody Map<String,Object>b){UserAccount u=role(r,"faculty","admin");Map<String,Object>a=new LinkedHashMap<>(b);a.put("createdBy",u.getId());Map<String,Object>saved=db.save("announcement",a,u.getId());for(UserAccount s:users.findAll())if(s.isActive()&&(s.getRole().equals("student")||s.getRole().equals("faculty")))db.notify(s.getId(),"Campus announcement",CampusService.s(a,"title","New announcement"));return ResponseEntity.status(201).body(ok("announcement",saved));}
